// strbasic.cpp - Basic string operations
#include <iostream>
#include <string>
using namespace std;

int main() {
    string first = "Computer";
    string second = "Science";

    string full = first + " " + second;       // concatenation
    cout << "Full      : " << full << endl;
    cout << "Length    : " << full.length() << endl;
    cout << "First char: " << full[0] << endl;
    cout << "Last char : " << full[full.length() - 1] << endl;
    cout << "full.at(3): " << full.at(3) << endl;

    full[0] = 'c';                            // strings can be changed
    cout << "Changed   : " << full << endl;

    string rep = "Ha";
    string laugh = "";
    for (int i = 0; i < 3; i++) laugh += rep;  // repetition with a loop
    cout << "Laugh     : " << laugh << endl;
    return 0;
}

// traverse.cpp - Traversing a string
#include <iostream>
#include <string>
using namespace std;

int main() {
    string word = "HELLO";

    // Method 1: index-based loop
    for (int i = 0; i < (int)word.length(); i++)
        cout << word[i] << " ";
    cout << endl;

    // Method 2: range-based for loop (C++11)
    for (char ch : word)
        cout << ch << "-";
    cout << endl;

    // Reverse traversal
    for (int i = word.length() - 1; i >= 0; i--)
        cout << word[i];
    cout << endl;
    return 0;
}

