// countchars.cpp - Count vowels, consonants, digits, spaces
#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    string s;
    cout << "Enter a sentence: ";
    getline(cin, s);
    int vowels = 0, consonants = 0, digits = 0, spaces = 0, others = 0;
    for (char ch : s) {
        char c = tolower(ch);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u')
            vowels++;
        else if (isalpha(c))
            consonants++;
        else if (isdigit(c))
            digits++;
        else if (c == ' ')
            spaces++;
        else
            others++;
    }
    cout << "Vowels     : " << vowels << endl;
    cout << "Consonants : " << consonants << endl;
    cout << "Digits     : " << digits << endl;
    cout << "Spaces     : " << spaces << endl;
    cout << "Others     : " << others << endl;
    return 0;
}

// palindrome.cpp - Check if a string is a palindrome
#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    cout << "Enter a word: ";
    cin >> s;

    string rev = "";
    for (int i = s.length() - 1; i >= 0; i--)
        rev += s[i];

    cout << "Reverse: " << rev << endl;
    if (s == rev)
        cout << s << " is a palindrome." << endl;
    else
        cout << s << " is not a palindrome." << endl;
    return 0;
}

// words.cpp - Count words and capitalise each word
#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    string s;
    cout << "Enter a sentence: ";
    getline(cin, s);

    int words = 0;
    bool newWord = true;
    for (int i = 0; i < (int)s.length(); i++) {
        if (s[i] == ' ') {
            newWord = true;
        } else if (newWord) {
            s[i] = toupper(s[i]);     // capitalise first letter
            words++;
            newWord = false;
        } else {
            s[i] = tolower(s[i]);
        }
    }
    cout << "Title case : " << s << endl;
    cout << "Word count : " << words << endl;
    return 0;
}

