#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    string s, clean = "";
    cout << "Enter a sentence: ";
    getline(cin, s);

    for (char ch : s)
        if (isalnum(ch))
            clean += tolower(ch);    // keep only letters/digits in lowercase

    bool pal = true;
    int n = clean.length();
    for (int i = 0; i < n / 2; i++) {
        if (clean[i] != clean[n - 1 - i]) {
            pal = false;
            break;
        }
    }
    cout << (pal ? "Palindrome" : "Not a palindrome") << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    string name;
    cout << "Enter full name: ";
    getline(cin, name);
    // (i) initials
    string initials = "";
    initials += toupper(name[0]);
    initials += '.';
    for (int i = 1; i < (int)name.length(); i++) {
        if (name[i - 1] == ' ' && name[i] != ' ') {
            initials += toupper(name[i]);
            initials += '.';
        }
    }
    cout << "Initials : " << initials << endl;

    // (ii) surname first
    int last = name.rfind(' ');
    string surname = name.substr(last + 1);
    string rest = name.substr(0, last);
    cout << "Formal   : " << surname << ", " << rest << endl;
    return 0;
}
